# AUTH SYSTEM
# ==========================================
USERS_FILE = "users.json"

def hash_password(password):
    return hashlib.sha256(password.encode()).hexdigest()

def load_users():
    if os.path.exists(USERS_FILE):
        with open(USERS_FILE, "r") as f:
            return json.load(f)
    return {}

def save_users(users):
    with open(USERS_FILE, "w") as f:
        json.dump(users, f)

users = load_users()

# ==========================================
# MASCOT IMAGE (base64 embedded)
# ==========================================
def get_mascot_base64():
    # Try loading from disk first (allows updating the image)
    search_paths = [
        "mascot.png",
        os.path.join(os.getcwd(), "mascot.png"),
    ]
    try:
        search_paths.append(os.path.join(os.path.dirname(os.path.abspath(__file__)), "mascot.png"))
    except Exception:
        pass
    for path in search_paths:
        if os.path.exists(path):
            with open(path, "rb") as f:
                return base64.b64encode(f.read()).decode()
    # Fallback: hardcoded base64 (always works)
    return ""

MASCOT_B64 = get_mascot_base64()

def mascot_html(size=80, extra_style=""):
    if MASCOT_B64:
        return f'<img src="data:image/png;base64,{MASCOT_B64}" width="{size}" style="border-radius:50%; {extra_style}" />'
    return "🐟"

