username = st.session_state.get("username")
FILENAME = f"budget_{username}.json"

DEFAULT_CATEGORIES = ["Food", "Transport", "Education", "Shopping", "Others"]

def load_data():
    if os.path.exists(FILENAME):
        with open(FILENAME, "r") as f:
            raw = json.load(f)
        # Migrate old format
        if "transactions" not in raw:
            raw["transactions"] = []
        if "income" not in raw:
            raw["income"] = 0.0
        if "savings_goals" not in raw:
            raw["savings_goals"] = {}
        if "savings_saved" not in raw:
            raw["savings_saved"] = {}
        return raw
    # Fresh user — pre-load default categories
    cats = {c: 0.0 for c in DEFAULT_CATEGORIES}
    return {
        "limits": cats,
        "spent": {c: 0.0 for c in DEFAULT_CATEGORIES},
        "total_budget": 0.0,
        "income": 0.0,
        "transactions": [],
        "savings_goals": {},
        "savings_saved": {},
    }

def save_data(d):
    with open(FILENAME, "w") as f:
        json.dump(d, f, indent=2)

