# TAB 4 – VISUALIZE (Spending Visualization — Donut + Bar)
# ============================================================
with tab_viz:
    st.markdown("### 🍩 Spending Visualization")
    total_spent_viz = sum(category_spent.values())

    if total_spent_viz == 0 or not category_limits:
        st.info("No spending data to visualize yet. Add some expenses first!")
    else:
        # Build donut chart with pure SVG (no external lib needed)
        cats_v  = [c for c in category_limits if category_spent.get(c, 0) > 0]
        amounts = [category_spent[c] for c in cats_v]
        total_v = sum(amounts)
        colors  = ["#a855f7","#3b82f6","#10b981","#f59e0b","#ef4444",
                   "#ec4899","#06b6d4","#84cc16","#f97316","#6366f1"]

        # Donut SVG
        cx, cy, r_outer, r_inner = 160, 160, 130, 75
        start = -90.0
        slices = []
        for amt, col in zip(amounts, colors[:len(amounts)]):
            angle = (amt / total_v) * 360
            slices.append((start, start + angle, col))
            start += angle

        def polar(cx, cy, r, angle_deg):
            import math
            rad = math.radians(angle_deg)
            return cx + r * math.cos(rad), cy + r * math.sin(rad)

        paths = []
        for (a1, a2, col) in slices:
            if abs(a2 - a1) < 0.01:
                continue
            large = 1 if (a2 - a1) > 180 else 0
            ox, oy = polar(cx, cy, r_outer, a1)
            ex, ey = polar(cx, cy, r_outer, a2)
            ix, iy = polar(cx, cy, r_inner, a2)
            jx, jy = polar(cx, cy, r_inner, a1)
            d = (f"M {ox:.2f} {oy:.2f} "
                 f"A {r_outer} {r_outer} 0 {large} 1 {ex:.2f} {ey:.2f} "
                 f"L {ix:.2f} {iy:.2f} "
                 f"A {r_inner} {r_inner} 0 {large} 0 {jx:.2f} {jy:.2f} Z")
            paths.append(f'<path d="{d}" fill="{col}" stroke="#1a0035" stroke-width="3"/>')

        donut_svg = f"""
        <svg width="320" height="320" viewBox="0 0 320 320" xmlns="http://www.w3.org/2000/svg">
            {''.join(paths)}
            <text x="160" y="150" text-anchor="middle" fill="#e9d5ff"
                  font-size="14" font-family="Nunito,sans-serif">Total Spent</text>
            <text x="160" y="175" text-anchor="middle" fill="#ffffff"
                  font-size="22" font-weight="bold" font-family="Nunito,sans-serif">
                ${total_v:.0f}
            </text>
        </svg>"""

        col_donut, col_legend = st.columns([1, 1])
        with col_donut:
            st.markdown(donut_svg, unsafe_allow_html=True)
        with col_legend:
            st.markdown("#### Category Breakdown")
            for cat, amt, col in zip(cats_v, amounts, colors[:len(cats_v)]):
                pct = amt / total_v * 100
                st.markdown(f"""
                <div style="display:flex; align-items:center; gap:10px; margin:6px 0;">
                    <div style="width:14px; height:14px; border-radius:3px;
                                background:{col}; flex-shrink:0;"></div>
                    <span style="color:#e9d5ff; flex:1;">{cat}</span>
                    <span style="color:#a855f7; font-weight:700;">{pct:.1f}%</span>
                    <span style="color:#94a3b8; font-size:0.85rem;">${amt:.2f}</span>
                </div>""", unsafe_allow_html=True)

        st.divider()

        # Bar chart — budget vs spent
        st.markdown("#### 📊 Budget vs. Spent per Category")
        for cat in category_limits:
            limit = category_limits[cat]
            spent = category_spent.get(cat, 0.0)
            if limit == 0:
                continue
            pct_spent  = min(spent  / limit * 100, 100)
            bar_color  = "#ef4444" if spent > limit else "#a855f7"
            st.markdown(f"""
            <div style="margin-bottom:10px;">
                <div style="display:flex; justify-content:space-between; color:#e2d9f3; font-size:0.9rem; margin-bottom:3px;">
                    <span><b>{cat}</b></span>
                    <span>${spent:.2f} / ${limit:.2f}</span>
                </div>
                <div style="background:rgba(255,255,255,0.1); border-radius:99px; height:10px; overflow:hidden;">
                    <div style="background:{bar_color}; width:{pct_spent:.1f}%;
                                height:100%; border-radius:99px; transition:width 0.4s;"></div>
                </div>
            </div>""", unsafe_allow_html=True)

# ============================================================
# TAB 5 – ANALYTICS (Monthly summaries, trend comparisons)
# ============================================================
with tab_analytics:
    st.markdown("### 📈 Budget Analytics")

    expense_txns_a = [t for t in transactions if t["type"] == "expense"]
    income_txns_a  = [t for t in transactions if t["type"] == "income"]

    if not expense_txns_a and not income_txns_a:
        st.info("No transaction data yet. Add income and expenses to see analytics.")
    else:
        # --- Monthly summary ---
        monthly = {}
        for t in transactions:
            d = t.get("date","")
            if len(d) >= 7:
                ym = d[:7]  # "YYYY-MM"
                if ym not in monthly:
                    monthly[ym] = {"income": 0.0, "expense": 0.0}
                if t["type"] == "income":
                    monthly[ym]["income"] += t["amount"]
                else:
                    monthly[ym]["expense"] += t["amount"]

        if monthly:
            st.markdown("#### 📅 Monthly Summaries")
            sorted_months = sorted(monthly.keys(), reverse=True)
            for ym in sorted_months[:6]:
                inc = monthly[ym]["income"]
                exp = monthly[ym]["expense"]
                bal = inc - exp
                try:
                    yr, mo = int(ym[:4]), int(ym[5:])
                    month_name = f"{calendar.month_name[mo]} {yr}"
                except:
                    month_name = ym
                color = "#4ade80" if bal >= 0 else "#f87171"
                m1, m2, m3, m4 = st.columns(4)
                with m1:
                    st.markdown(f'<div class="analytic-card"><h3>{month_name}</h3><p>Month</p></div>', unsafe_allow_html=True)
                with m2:
                    st.markdown(f'<div class="analytic-card"><h3 style="color:#4ade80;">${inc:.2f}</h3><p>Income</p></div>', unsafe_allow_html=True)
                with m3:
                    st.markdown(f'<div class="analytic-card"><h3 style="color:#f87171;">${exp:.2f}</h3><p>Spent</p></div>', unsafe_allow_html=True)
                with m4:
                    st.markdown(f'<div class="analytic-card"><h3 style="color:{color};">${bal:.2f}</h3><p>Balance</p></div>', unsafe_allow_html=True)
                st.write("")

        st.divider()

        # --- Spending trends: this month vs last month ---
        st.markdown("#### 🔄 Spending Trend Comparison")
        today = date.today()
        this_mo = today.strftime("%Y-%m")
        last_mo_date = date(today.year, today.month - 1, 1) if today.month > 1 else date(today.year - 1, 12, 1)
        last_mo = last_mo_date.strftime("%Y-%m")

        this_total = monthly.get(this_mo, {}).get("expense", 0.0)
        last_total = monthly.get(last_mo, {}).get("expense", 0.0)

        tc1, tc2, tc3 = st.columns(3)
        with tc1:
            st.markdown(f'<div class="analytic-card"><h3 style="color:#f87171;">${last_total:.2f}</h3><p>Last Month Spending</p></div>', unsafe_allow_html=True)
        with tc2:
            st.markdown(f'<div class="analytic-card"><h3 style="color:#f87171;">${this_total:.2f}</h3><p>This Month Spending</p></div>', unsafe_allow_html=True)
        with tc3:
            diff   = this_total - last_total
            dcolor = "#f87171" if diff > 0 else "#4ade80"
            dsign  = "+" if diff > 0 else ""
            st.markdown(f'<div class="analytic-card"><h3 style="color:{dcolor};">{dsign}${diff:.2f}</h3><p>Change vs Last Month</p></div>', unsafe_allow_html=True)

        st.divider()

        # --- Top spending categories ---
        st.markdown("#### 🏆 Top Spending Categories (All Time)")
        if expense_txns_a:
            cat_totals = {}
            for t in expense_txns_a:
                cat_totals[t["category"]] = cat_totals.get(t["category"], 0.0) + t["amount"]
            sorted_cats = sorted(cat_totals.items(), key=lambda x: x[1], reverse=True)
            medals = ["🥇","🥈","🥉","4️⃣","5️⃣"]
            for i, (cat, total) in enumerate(sorted_cats[:5]):
                medal = medals[i] if i < len(medals) else "▪️"
                st.markdown(f"""
                <div style="display:flex; justify-content:space-between; align-items:center;
                            padding:10px 16px; background:rgba(255,255,255,0.05);
                            border-radius:10px; margin-bottom:6px;">
                    <span style="color:#e9d5ff;">{medal} <b>{cat}</b></span>
                    <span style="color:#f87171; font-weight:700;">${total:.2f}</span>
                </div>""", unsafe_allow_html=True)

        # --- Budget utilisation overall ---
        st.divider()
        st.markdown("#### 🎯 Overall Budget Utilisation")
        if total_budget_limit > 0:
            total_spent_all2 = sum(category_spent.values())
            util = min(total_spent_all2 / total_budget_limit * 100, 100)
            color_u = "#ef4444" if util > 90 else "#f59e0b" if util > 70 else "#10b981"
            st.markdown(f"""
            <div style="margin:10px 0;">
                <div style="display:flex; justify-content:space-between; color:#e2d9f3; margin-bottom:4px;">
                    <span>Budget Used</span>
                    <span style="color:{color_u}; font-weight:700;">{util:.1f}%</span>
                </div>
                <div style="background:rgba(255,255,255,0.1); border-radius:99px; height:16px; overflow:hidden;">
                    <div style="background:{color_u}; width:{util:.1f}%; height:100%; border-radius:99px;"></div>
                </div>
                <div style="display:flex; justify-content:space-between; color:#94a3b8; font-size:0.8rem; margin-top:4px;">
                    <span>${total_spent_all2:.2f} spent</span>
                    <span>${total_budget_limit:.2f} budget</span>
                </div>
            </div>""", unsafe_allow_html=True)
        else:
            st.info("Set a master budget in ⚙️ Manage to see utilisation.")

# ============================================================
# TAB 6 – SAVINGS TRACKER
# ============================================================
with tab_savings:
    st.markdown("### 🐖 Savings Goals Tracker")
    st.markdown("Set savings goals and track how much you've saved toward each one.")

    # Add new goal
    with st.expander("➕ Add New Savings Goal", expanded=not bool(savings_goals)):
        with st.form("savings_form", clear_on_submit=True):
            goal_name   = st.text_input("Goal Name", placeholder="e.g. New Headphones, School Trip")
            goal_target = st.number_input("Target Amount ($)", min_value=1.0, step=5.0)
            submitted_g = st.form_submit_button("Create Goal", use_container_width=True)
            if submitted_g:
                if not goal_name.strip():
                    st.error("Please enter a goal name.")
                elif goal_name in savings_goals:
                    st.error("A goal with that name already exists.")
                else:
                    savings_goals[goal_name] = goal_target
                    savings_saved[goal_name] = savings_saved.get(goal_name, 0.0)
                    save_data(data)
                    st.session_state.data = data
                    st.success(f"✅ Goal '{goal_name}' created!")
                    st.rerun()

    st.divider()

    if not savings_goals:
        st.info("No savings goals yet. Create one above!")
    else:
        for goal, target in list(savings_goals.items()):
            saved  = savings_saved.get(goal, 0.0)
            pct    = min(saved / target * 100, 100) if target > 0 else 0
            remain = max(target - saved, 0.0)
            done   = saved >= target

            bar_col = "#10b981" if done else "#3b82f6"
            st.markdown(f"""
            <div class="savings-card">
                <div style="display:flex; justify-content:space-between; align-items:center;">
                    <h4>{'🎉 ' if done else '🎯 '}{goal}</h4>
                    <span style="color:{'#4ade80' if done else '#93c5fd'}; font-weight:700;">
                        {'ACHIEVED! 🎉' if done else f'${remain:.2f} to go'}
                    </span>
                </div>
                <div style="background:rgba(255,255,255,0.1); border-radius:99px; height:12px; overflow:hidden; margin:8px 0;">
                    <div style="background:{bar_col}; width:{pct:.1f}%; height:100%; border-radius:99px;"></div>
                </div>
                <p>${saved:.2f} saved of ${target:.2f} target &nbsp;·&nbsp; {pct:.0f}% complete</p>
            </div>""", unsafe_allow_html=True)

            col_add, col_del = st.columns([3, 1])
            with col_add:
                add_amt = st.number_input(
                    f"Add savings to '{goal}' ($)",
                    min_value=0.01, step=1.0, key=f"sv_{goal}"
                )
            with col_del:
                st.write("")
                st.write("")
                if st.button(f"➕ Save", key=f"btn_sv_{goal}", use_container_width=True):
                    savings_saved[goal] = savings_saved.get(goal, 0.0) + add_amt
                    save_data(data)
                    st.session_state.data = data
                    st.success(f"Added ${add_amt:.2f} to '{goal}'!")
                    st.rerun()

            if st.button(f"🗑️ Delete '{goal}'", key=f"del_sv_{goal}"):
                del savings_goals[goal]
                if goal in savings_saved:
                    del savings_saved[goal]
                save_data(data)
                st.session_state.data = data
                st.rerun()

            st.write("")

# ============================================================
# TAB 7 – MANAGE (Setup)
# ============================================================
with tab_manage:
    st.markdown("### ⚙️ App Setup & Management")

    # --- Master budget ---
    st.markdown("#### 1️⃣ Set Master Monthly Budget")
    with st.form("budget_form"):
        new_budget = st.number_input(
            "Total Monthly Budget ($)",
            min_value=0.0,
            value=float(total_budget_limit),
            step=10.0
        )
        submitted_b = st.form_submit_button("💾 Save Budget", use_container_width=True)
        if submitted_b:
            allocated = sum(category_limits.values())
            if new_budget < allocated:
                st.error(f"Budget (${new_budget:.2f}) is less than already-allocated category limits (${allocated:.2f}). Increase it or reduce category limits first.")
            else:
                data["total_budget"] = new_budget
                save_data(data)
                st.session_state.data = data
                st.success(f"✅ Master budget set to ${new_budget:.2f}")
                st.rerun()

    st.divider()

    # --- Categories ---
    st.markdown("#### 2️⃣ Manage Categories")
    st.caption("Default categories: Food, Transport, Education, Shopping, Others")

    with st.form("cat_form", clear_on_submit=True):
        c1, c2 = st.columns(2)
        with c1:
            cat_name  = st.text_input("Category Name", placeholder="e.g. Entertainment")
        with c2:
            cat_limit = st.number_input("Spending Limit ($)", min_value=0.0, step=5.0)
        submitted_c = st.form_submit_button("➕ Add / Update Category", use_container_width=True)
        if submitted_c:
            cat_name = cat_name.strip()
            if not cat_name:
                st.error("Category name cannot be empty.")
            else:
                current_alloc = sum(v for k, v in category_limits.items() if k != cat_name)
                if current_alloc + cat_limit > data["total_budget"] and data["total_budget"] > 0:
                    st.error(f"Adding ${cat_limit:.2f} would exceed master budget of ${data['total_budget']:.2f}. Raise master budget first.")
                else:
                    category_limits[cat_name] = cat_limit
                    if cat_name not in category_spent:
                        category_spent[cat_name] = 0.0
                    save_data(data)
                    st.session_state.data = data
                    st.success(f"✅ Category '{cat_name}' saved with ${cat_limit:.2f} limit.")
                    st.rerun()

    # Existing categories
    if category_limits:
        st.markdown("##### Existing Categories")
        for cat in list(category_limits.keys()):
            cc1, cc2, cc3 = st.columns([2, 2, 1])
            with cc1:
                st.markdown(f"<span style='color:#e9d5ff; font-weight:600;'>{cat}</span>", unsafe_allow_html=True)
            with cc2:
                spent_c = category_spent.get(cat, 0.0)
                limit_c = category_limits[cat]
                st.markdown(f"<span style='color:#94a3b8; font-size:0.85rem;'>Limit: ${limit_c:.2f} | Spent: ${spent_c:.2f}</span>", unsafe_allow_html=True)
            with cc3:
                if st.button("🗑️", key=f"del_cat_{cat}"):
                    del category_limits[cat]
                    if cat in category_spent:
                        del category_spent[cat]
                    save_data(data)
                    st.session_state.data = data
                    st.rerun()

    st.divider()

    # --- Danger zone ---
    st.markdown("#### ⚠️ Danger Zone")
    confirm_reset = st.checkbox("I understand this will permanently delete ALL my data")
    if st.button("🔄 Reset All Data", type="primary"):
        if confirm_reset:
            fresh = {
                "limits": {c: 0.0 for c in DEFAULT_CATEGORIES},
                "spent":  {c: 0.0 for c in DEFAULT_CATEGORIES},
                "total_budget": 0.0,
                "income": 0.0,
                "transactions": [],
                "savings_goals": {},
                "savings_saved": {},
            }
            save_data(fresh)
            st.session_state.data = fresh
            st.success("✅ All data reset.")
            st.rerun()
        else:
            st.error("Please tick the confirmation box first.")

    st.divider()
    st.markdown(
        f"""
        <div style="text-align:center; opacity:0.6; margin-top:12px;">
            {mascot_html(size=44, extra_style="box-shadow:0 0 12px 2px #a855f7;")}
            <p style="color:#c4b5fd; font-size:0.78rem; margin-top:6px;">
                Fluxadia keeps your budget on track 🚀
            </p>
        </div>
        """,
        unsafe_allow_html=True
    )
